'use client'

import { ExternalLink, FileText } from 'lucide-react'
import { PageHeader } from '@/admin/components/layout/PageHeader'
import flows from '@/admin/lib/flow-docs.json'

// Guides, grouped by category. The flow PDFs are generated by docs/flows/build.py into public/docs/flows and
// the installation manual by docs/guide/build.mjs into public/docs/guides; this page lists them from the one
// generated flow-docs.json (title, category, version, description), so a new guide appears after a rebuild.
type Doc = {
  file: string
  href?: string
  title: string
  goal: string
  category?: string
  version?: string
}

const docs = flows as Doc[]
const categories = [...new Set(docs.map((d) => d.category ?? 'Guides'))]

export default function DocumentsPage() {
  return (
    <div className="max-w-4xl space-y-6">
      <PageHeader title="Documents" breadcrumbs={[{ label: 'Documents' }]} />
      <p className="text-sm text-muted-foreground">
        Guides for installing and using KDL OS. Each one opens as a PDF in a new tab.
      </p>
      {categories.map((category) => (
        <section key={category} aria-labelledby={`cat-${category}`} className="space-y-3">
          <h2 id={`cat-${category}`} className="text-lg font-semibold">
            {category}
          </h2>
          <ul className="grid gap-3 sm:grid-cols-2" aria-label={category}>
            {docs
              .filter((d) => (d.category ?? 'Guides') === category)
              .map((f) => (
                <li key={f.file}>
                  <a
                    href={f.href ?? `/docs/flows/${f.file}`}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="flex h-full items-start gap-3 rounded-lg border bg-card p-4 transition-colors hover:border-primary hover:bg-accent"
                  >
                    <FileText className="mt-0.5 h-5 w-5 shrink-0 text-primary" aria-hidden="true" />
                    <span className="min-w-0 flex-1">
                      <span className="flex items-center gap-1.5 font-medium">
                        {f.title}
                        <ExternalLink
                          className="h-3.5 w-3.5 text-muted-foreground"
                          aria-hidden="true"
                        />
                        <span className="sr-only">(opens in a new tab)</span>
                      </span>
                      <span className="mt-1 block text-sm text-muted-foreground">{f.goal}</span>
                      {f.version && (
                        <span className="mt-1 block text-xs text-muted-foreground">
                          PDF · Version {f.version}
                        </span>
                      )}
                    </span>
                  </a>
                </li>
              ))}
          </ul>
        </section>
      ))}
    </div>
  )
}
